const input = items[0].json;
const lang = input.language || 'Unknown';
const translate = input.translate || '';
const transcription = input.transcription || '';

// 決定檢查長度的目標 (優先看翻譯)
const mainContent = translate.length > 0 ? translate : transcription;

// 門檻值: 500
if (mainContent.length > 500) {
  let fileContent = `Language: ${lang}\n\n`;
  if (translate) {
    fileContent += `=== 繁體中文翻譯 ===\n${translate}\n\n`;
  }
  fileContent += `=== 原始轉錄內容 ===\n${transcription}`;

  return {
    json: {
      ...input,
      uploadFile: true,
      summaryText: `⚠️ 翻譯/轉錄內容共 ${mainContent.length} 字，已轉存為附件 (stt_result.txt)。`
    },
    binary: {
      data: {
        data: Buffer.from(fileContent).toString('base64'),
        mimeType: 'text/plain',
        fileName: `stt_result_${Date.now()}.txt`
      }
    }
  };
} else {
  return {
    json: {
      ...input,
      uploadFile: false
    }
  };
}

const input = items[0].json;
const inspectionData = input.sttInspection || [];
let analysisText = "";

if (Array.isArray(inspectionData)) {
  // 將 Array 轉為易讀文字
  analysisText = inspectionData.map((item, index) => {
    return `[問題 ${index + 1}]\n描述: ${item.issue}\n引用: "${item.ref}"`;
  }).join('\n\n----------------\n\n');
} else {
  // 防呆
  analysisText = JSON.stringify(inspectionData, null, 2);
}

// 門檻值: 500
if (analysisText.length > 500) {
  const fileContent = `=== 直播問題分析報告 ===\n\n${analysisText}`;

  return {
    json: {
      ...input,
      uploadFile: true,
      summaryText: `⚠️ 分析報告過長 (${analysisText.length} 字)，請查看附件 (stt_analysis.txt)。`
    },
    binary: {
      data: {
        data: Buffer.from(fileContent).toString('base64'),
        mimeType: 'text/plain',
        fileName: `stt_analysis_${Date.now()}.txt`
      }
    }
  };
} else {
  return {
    json: {
      ...input,
      uploadFile: false,
      formattedAnalysisText: analysisText
    }
  };
}
